// Shared helpers for animated html_tailwind beats: timing curves, deterministic noise, fonts, text sampling,
// and miniFilm() (tiny code-drawn films for screens). Pasted in front of every scene script by build.py.
const el = (id) => document.getElementById(id);
const clamp01 = (t) => Math.max(0, Math.min(1, t));
const seg = (t, a, b) => clamp01((t - a) / (b - a));
const lerp = (a, b, k) => a + (b - a) * k;
const ease = (t) => { t = clamp01(t); return t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2; };
const easeOut = (t) => 1 - Math.pow(1 - clamp01(t), 3);
const easeIn = (t) => Math.pow(clamp01(t), 3);
const back = (t) => { t = clamp01(t); const c1 = 1.70158, c3 = c1 + 1; return 1 + c3 * Math.pow(t - 1, 3) + c1 * Math.pow(t - 1, 2); };
const fadeInOut = (t, a, b, f = 0.25) => Math.min(seg(t, a, a + f), 1 - seg(t, b - f, b));
const flashAfter = (t, start, dur = 0.12) => (t >= start ? 1 - seg(t, start, start + dur) : 0);
let fontsReady = false;
const waitFonts = async () => { if (!fontsReady) { await document.fonts.ready; fontsReady = true; } };
const rnd = (n) => { const x = Math.sin(n * 127.1 + 311.7) * 43758.5453; return x - Math.floor(x); };
const pad = (n, w) => String(n).padStart(w, '0');
// fade the whole beat in and out so cuts between beats breathe
const beatFade = (t, D, i = 0.25, o = 0.25) => { el('bf').style.opacity = 1 - Math.min(seg(t, 0, i), 1 - seg(t, D - o, D)); };
// points covering text drawn in a font — targets for particle type
const textTargets = (txt, font, w, h, step, dx = 0, dy = 0) => {
  const c = document.createElement('canvas'); c.width = w; c.height = h; const g = c.getContext('2d');
  g.fillStyle = '#fff'; g.font = font; g.textAlign = 'center'; g.textBaseline = 'middle'; g.fillText(txt, w / 2, h / 2);
  const d = g.getImageData(0, 0, w, h).data, pts = [];
  for (let y = 0; y < h; y += step) for (let x = 0; x < w; x += step) if (d[(y * w + x) * 4 + 3] > 128) pts.push([x + dx, y + dy]);
  return pts;
};
// tiny code-drawn films, shared by several beats
const miniFilm = (g, k, x, y, w, h, t) => {
  g.save(); g.beginPath(); g.rect(x, y, w, h); g.clip();
  if (k === 0) {
    const sky = g.createLinearGradient(0, y, 0, y + h); sky.addColorStop(0, '#2b1a4d'); sky.addColorStop(0.55, '#ff8a5c'); sky.addColorStop(0.56, '#1b3a5c'); sky.addColorStop(1, '#0a1a2c');
    g.fillStyle = sky; g.fillRect(x, y, w, h);
    g.fillStyle = '#ffd59a'; g.beginPath(); g.arc(x + w * 0.5, y + h * 0.55, h * 0.18, Math.PI, 0); g.fill();
    g.strokeStyle = 'rgba(255,200,150,.6)'; g.lineWidth = Math.max(1, h / 70);
    for (let r = 0; r < 5; r++) { g.beginPath(); for (let i = 0; i <= w; i += 6) { const yy = y + h * (0.62 + r * 0.08) + Math.sin(i * 0.05 + t * 2 + r) * h * 0.02; i ? g.lineTo(x + i, yy) : g.moveTo(x + i, yy); } g.stroke(); }
  } else if (k === 1) {
    g.fillStyle = '#081426'; g.fillRect(x, y, w, h);
    for (let b = 0; b < 12; b++) {
      const bw = w / 12, bh = h * (0.35 + 0.5 * rnd(b * 9.1)), bx = x + b * bw;
      g.fillStyle = '#10243c'; g.fillRect(bx + 1, y + h - bh, bw - 2, bh);
      const s = Math.max(3, h / 30);
      for (let wy = y + h - bh + s * 1.5; wy < y + h - s; wy += s * 2.2) for (let wx = bx + s; wx < bx + bw - s; wx += s * 1.8)
        if (rnd(Math.floor(wx) * 3.3 + Math.floor(wy) * 7.7 + Math.floor(t * 3 + rnd(wx) * 5)) > 0.55) { g.fillStyle = 'rgba(255,214,140,.9)'; g.fillRect(wx, wy, s * 0.7, s); }
    }
  } else if (k === 2) {
    g.fillStyle = '#05060f'; g.fillRect(x, y, w, h);
    for (let i = 0; i < 300; i++) {
      const a = rnd(i) * 6.283 + t * 0.6 + (i % 2) * Math.PI, rr = Math.pow(rnd(i * 5.1), 0.7) * h * 0.55, sw = a + rr / h * 2.5;
      g.fillStyle = `rgba(${180 + 75 * rnd(i * 2)},${170 + 60 * rnd(i * 3)},255,${0.4 + 0.6 * rnd(i * 4)})`;
      g.fillRect(x + w / 2 + Math.cos(sw) * rr * 1.5, y + h / 2 + Math.sin(sw) * rr * 0.6, Math.max(1.5, h / 90), Math.max(1.5, h / 90));
    }
  } else if (k === 3) {
    g.fillStyle = '#071a1f'; g.fillRect(x, y, w, h);
    for (let i = 0; i < 38; i++) {
      const v = 0.2 + 0.8 * Math.abs(Math.sin(i * 0.7 + t * 5) * Math.sin(i * 0.23 + t * 1.3));
      g.fillStyle = `hsl(${170 + i * 2},80%,60%)`; g.fillRect(x + w * 0.04 + i * (w * 0.92) / 38, y + h / 2 - v * h * 0.38, (w * 0.92) / 38 - 2, v * h * 0.76);
    }
  } else {
    const bg = g.createLinearGradient(x, y, x + w, y + h); bg.addColorStop(0, '#1d1236'); bg.addColorStop(1, '#0a1630'); g.fillStyle = bg; g.fillRect(x, y, w, h);
    const cx = x + w * 0.5 + Math.sin(t * 0.8) * w * 0.02;
    g.fillStyle = '#05070c'; g.beginPath(); g.arc(cx, y + h * 0.42, h * 0.2, 0, 6.283); g.fill();
    g.beginPath(); g.ellipse(cx, y + h * 1.02, w * 0.3, h * 0.38, 0, Math.PI, 0); g.fill();
    g.strokeStyle = 'rgba(255,170,120,.9)'; g.lineWidth = Math.max(2, h / 45); g.beginPath(); g.arc(cx, y + h * 0.42, h * 0.2, -1.2, 0.6); g.stroke();
  }
  g.fillStyle = 'rgba(0,0,0,.16)'; for (let yy = y; yy < y + h; yy += 4) g.fillRect(x, yy, w, 1);
  g.restore();
};
// Footage: mulmocast re-seeks every <video> to the beat's own time after render() returns (html_render.ts,
// syncVideosToFrame), so a visible <video> never shows the time you asked for. Keep the <video> hidden, seek it
// yourself, and paint the decoded frame into a canvas; the canvas keeps it when mulmocast re-seeks.
const seekTo = (v, t) => new Promise((res) => {
  const go = () => {
    if (Math.abs(v.currentTime - t) < 0.0005) return res();
    v.addEventListener('seeked', function h() { v.removeEventListener('seeked', h); res(); });
    v.currentTime = t;
  };
  if (v.readyState >= 2) go(); else v.addEventListener('loadeddata', go, { once: true });
});
const paint = async (vid, cid, t, sx = 0, sy = 0, sw = null, sh = null) => {
  const v = el(vid); await seekTo(v, t);
  const c = el(cid); c.getContext('2d').drawImage(v, sx, sy, sw ?? v.videoWidth, sh ?? v.videoHeight, 0, 0, c.width, c.height);
};

// three.js r147 helpers, with the fixes found while building the AI Short Film Fes remake (2026-09-29):
// MSAA on the composer, a dark studio environment instead of RoomEnvironment, reflections kept on bright metals only,
// an opaque canvas, no tone mapping by default, and chamfered frames whose holes stay open. Pasted after common.js.
const chamfer = (w, h, c) => {
  const s = new THREE.Shape();
  s.moveTo(-w / 2 + c, -h / 2); s.lineTo(w / 2 - c, -h / 2); s.lineTo(w / 2, -h / 2 + c); s.lineTo(w / 2, h / 2 - c);
  s.lineTo(w / 2 - c, h / 2); s.lineTo(-w / 2 + c, h / 2); s.lineTo(-w / 2, h / 2 - c); s.lineTo(-w / 2, -h / 2 + c); s.closePath();
  return s;
};
const fitUV = (g, w, h) => { const p = g.attributes.position, uv = g.attributes.uv; for (let i = 0; i < p.count; i++) uv.setXY(i, p.getX(i) / w + 0.5, p.getY(i) / h + 0.5); uv.needsUpdate = true; return g; };
const ringOf = (w, h, c, th) => { const o = chamfer(w, h, c); o.holes.push(chamfer(w - th * 2, h - th * 2, Math.max(0.001, c - th * 0.4142))); return new THREE.ShapeGeometry(o); };
const dotTex = (rgb) => {
  const c = document.createElement('canvas'); c.width = c.height = 64; const g = c.getContext('2d');
  const r = g.createRadialGradient(32, 32, 0, 32, 32, 32); r.addColorStop(0, 'rgba(255,255,255,1)'); r.addColorStop(0.3, `rgba(${rgb},.8)`); r.addColorStop(1, `rgba(${rgb},0)`);
  g.fillStyle = r; g.fillRect(0, 0, 64, 64); return new THREE.CanvasTexture(c);
};
// scene.environment = RoomEnvironment lights every material with a bright white studio; dark floors and props then
// read as pale grey clay (round-1 renders). On the first render of each scene, keep the reflections only on bright
// metals (gold, chrome) and turn them almost off everywhere else.
const tameEnv = (scene) => {
  scene.traverse((o) => {
    const mats = o.material ? (Array.isArray(o.material) ? o.material : [o.material]) : [];
    mats.forEach((m) => {
      if (!m.isMeshStandardMaterial) return;
      const lum = m.color ? 0.2126 * m.color.r + 0.7152 * m.color.g + 0.0722 * m.color.b : 0;
      m.envMapIntensity = m.metalness >= 0.75 && lum > 0.25 ? Math.max(m.envMapIntensity, 1.8) : Math.min(m.envMapIntensity, 0.12);
    });
  });
};
// RoomEnvironment is a light grey room, so gold reflected grey and read as olive bronze. Scenes that ask for it get a
// dark studio instead: a black sphere with a warm softbox, a cool strip and a small hot key — contrasty reflections.
class StudioEnv extends THREE.Scene {
  constructor() {
    super();
    const add = (geo, rgb, k, pos, look) => { const m = new THREE.Mesh(geo, new THREE.MeshBasicMaterial({ color: new THREE.Color(rgb).multiplyScalar(k), side: THREE.DoubleSide })); m.position.set(...pos); m.lookAt(...look); this.add(m); };
    this.add(new THREE.Mesh(new THREE.SphereGeometry(30, 32, 16), new THREE.MeshBasicMaterial({ color: 0x07090d, side: THREE.BackSide })));
    add(new THREE.PlaneGeometry(14, 9), 0xffe2b0, 5, [-12, 10, 10], [0, 0, 0]);   // warm softbox, upper left front
    add(new THREE.PlaneGeometry(3, 18), 0x9fd8ff, 4, [14, 2, -4], [0, 0, 0]);    // cool strip, right
    add(new THREE.PlaneGeometry(3, 3), 0xffffff, 14, [2, 4, 16], [0, 0, 0]);     // small hot key, front
    add(new THREE.PlaneGeometry(26, 4), 0xffc070, 1.2, [0, -12, 0], [0, 0, 0]);  // warm bounce from below
  }
  dispose() { this.traverse((o) => { if (o.geometry) o.geometry.dispose(); if (o.material) o.material.dispose(); }); }  // RoomEnvironment has it; scenes call it
}
if (THREE.RoomEnvironment) THREE.RoomEnvironment = StudioEnv;
const _r3render = THREE.WebGLRenderer.prototype.render;
THREE.WebGLRenderer.prototype.render = function (scene, camera) {
  if (scene && scene.isScene && !scene.__tamed) { tameEnv(scene); scene.__tamed = true; }
  return _r3render.call(this, scene, camera);
};
const makeRenderer = (id, bloom = [0.8, 0.3, 0.95]) => {
  const R = new THREE.WebGLRenderer({ canvas: el(id), antialias: true, alpha: false, preserveDrawingBuffer: true });
  R.setPixelRatio(1); R.setSize(1280, 720, false); R.toneMapping = THREE.NoToneMapping;
  const scene = new THREE.Scene(); const cam = new THREE.PerspectiveCamera(35, 16 / 9, 0.1, 200);
  // `antialias: true` only covers drawing straight to the canvas; the composer renders into its own targets, which had
  // no anti-aliasing, so thin tilted lines (the judge's gold frames) came out stair-stepped. 4x MSAA on those targets.
  const rt = new THREE.WebGLRenderTarget(1280, 720, { samples: 4, type: THREE.HalfFloatType });
  const composer = new THREE.EffectComposer(R, rt); composer.addPass(new THREE.RenderPass(scene, cam));
  composer.addPass(new THREE.UnrealBloomPass(new THREE.Vector2(1280, 720), bloom[0], bloom[1], bloom[2]));
  return { R, scene, cam, composer };
};

const D = 9.0; const P = {"eyebrow": "CHAPTER ONE", "title": "First Light"}; const TOTAL_FRAMES = 1740;
// Alpine dawn: deterministic heightfields, horizon shadows and a lit cloud inversion.
let peaksState;

function peaksNoise(x, y) {
  const ix = Math.floor(x), iy = Math.floor(y);
  let u = x - ix, v = y - iy;
  u = u * u * (3 - 2 * u); v = v * v * (3 - 2 * v);
  return lerp(lerp(rnd(ix + iy * 173.17), rnd(ix + 1 + iy * 173.17), u),
    lerp(rnd(ix + (iy + 1) * 173.17), rnd(ix + 1 + (iy + 1) * 173.17), u), v);
}
function peaksFbm(x, y, octaves = 5) {
  let value = 0, weight = .5;
  for (let i = 0; i < octaves; i++) {
    value += weight * peaksNoise(x, y);
    const nx = 1.72 * x + 1.07 * y + 13.8;
    y = -1.07 * x + 1.72 * y + 8.3; x = nx; weight *= .5;
  }
  return value;
}
const peaksGLSL = `
float hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
float noise(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.-2.*f);
return mix(mix(hash(i),hash(i+vec2(1,0)),f.x),mix(hash(i+vec2(0,1)),hash(i+1.),f.x),f.y);}
float fbm(vec2 p){float f=0.,a=.5;for(int i=0;i<4;i++){f+=a*noise(p);p=mat2(1.72,-1.07,1.07,1.72)*p+13.7;a*=.5;}return f;}
`;

function peaksTerrain(scene, config) {
  const { z, width, depth, height, seed, centers } = config;
  const nx = 300, nz = 100;
  const geo = new THREE.PlaneGeometry(width, depth, nx, nz);
  geo.rotateX(-Math.PI / 2);
  const pos = geo.attributes.position, heights = new Float32Array(pos.count);
  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i), localZ = pos.getZ(i);
    const warp = (peaksFbm(x * .014 + seed, localZ * .015) - .45) * 25;
    let massif = 0;
    for (const peak of centers) {
      const dx = (x - peak[0] + warp) / peak[2];
      const dz = (localZ - peak[1]) / (depth * .34);
      massif = Math.max(massif, peak[3] * Math.exp(-dx * dx * 1.6 - dz * dz * 1.8));
    }
    let ridge = 0, amplitude = .55, frequency = .026;
    for (let k = 0; k < 6; k++) {
      const n = peaksNoise((x + warp) * frequency + seed * 11, localZ * frequency + seed);
      ridge += amplitude * (1 - Math.abs(n * 2 - 1));
      frequency *= 2.12; amplitude *= .49;
    }
    // Eroded ribs reach down from each summit; a broad envelope avoids isolated cones.
    const h = 5 + height * massif * (.48 + .62 * ridge) + 6 * peaksFbm(x * .06, localZ * .07 + seed);
    heights[i] = h; pos.setY(i, h); pos.setZ(i, localZ + z);
  }
  geo.computeVertexNormals();
  const shadows = new Float32Array(pos.count);
  // Trace the heightfield toward the low sun. This bakes cast shadows into the actual valleys.
  for (let j = 0; j <= nz; j++) for (let i = 0; i <= nx; i++) {
    const index = j * (nx + 1) + i, h = heights[index];
    let blocked = 0;
    for (let step = 1; step <= 22; step++) {
      const sx = i + Math.round(step * 1.35), sz = j - step;
      if (sx > nx || sz < 0) break;
      const distance = Math.hypot((sx - i) * width / nx, step * depth / nz);
      blocked = Math.max(blocked, clamp01((heights[sz * (nx + 1) + sx] - h - distance * .095) / 5));
    }
    shadows[index] = 1 - blocked * .91;
  }
  geo.setAttribute('sunVisibility', new THREE.BufferAttribute(shadows, 1));
  const mat = new THREE.ShaderMaterial({
    uniforms: { snowLine: { value: height * .59 }, sun: { value: new THREE.Vector3(.41, .075, -.907).normalize() } },
    vertexShader: `attribute float sunVisibility; varying vec3 w,n; varying float visibility;
      void main(){w=position;n=normal;visibility=sunVisibility;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);}`,
    fragmentShader: `${peaksGLSL}
      uniform float snowLine;uniform vec3 sun;varying vec3 w,n;varying float visibility;
      void main(){
        vec3 normal=normalize(n);
        float detail=fbm(w.xz*.38);
        float strata=noise(vec2(w.x*.11+w.y*.45,w.z*.14))* .5+.5;
        float snow=smoothstep(snowLine-9.,snowLine+13.,w.y+detail*16.) * smoothstep(.38,.77,normal.y+(detail-.5)*.3);
        vec3 rock=mix(vec3(.071,.087,.109),vec3(.26,.235,.209),detail)*strata;
        vec3 albedo=mix(rock,vec3(.72,.79,.85),snow);
        float diffuse=max(0.,dot(normal,sun))*visibility;
        // Cool open-sky fill keeps the unlit rock readable. A broad warm horizon
        // wraps the grazing key around east-facing ribs without lifting all shadows.
        float east=smoothstep(-.12,.65,normal.x)*visibility;
        float summit=smoothstep(snowLine-24.,snowLine+18.,w.y);
        float rim=pow(1.-max(0.,dot(normal,normalize(cameraPosition-w))),2.);
        vec3 light=vec3(.40,.56,.84)*(.55+.45*max(normal.y,0.))
          +vec3(2.35,1.18,.52)*diffuse
          +vec3(.95,.40,.22)*east*(.3+.7*summit);
        vec3 color=albedo*light;
        color+=vec3(.43,.20,.09)*rim*east*summit;
        // Gentle highlight shoulder: retain pink/gold in snow, never clip it white.
        color=color/(vec3(1.)+color*.48);
        float dist=length(cameraPosition-w);
        float haze=1.-exp(-max(0.,dist-85.)*.00185);
        vec3 air=mix(vec3(.20,.29,.40),vec3(.47,.43,.43),exp(-max(w.y-22.,0.)*.045));
        color=mix(color,air,haze*.83);
        gl_FragColor=vec4(color,1.);
      }`
  });
  const mesh = new THREE.Mesh(geo, mat); scene.add(mesh);
  return mat;
}

async function setupPeaks() {
  await waitFonts();
  el('peaks-eyebrow').textContent = P.eyebrow;
  el('peaks-title').textContent = P.title;
  // Fit arbitrary replacement titles while retaining the airy one-line default.
  const title = el('peaks-title');
  if (title.scrollWidth > 760) title.style.fontSize = `${Math.max(54, 100 * 760 / title.scrollWidth)}px`;
  const S = makeRenderer('peaks-canvas', [.30, .72, .94]);
  const { scene, cam } = S;
  cam.fov = 43; cam.near = 1; cam.far = 2400; cam.updateProjectionMatrix();
  const sunDirection = new THREE.Vector3(.41, .075, -.907).normalize();
  const sky = new THREE.Mesh(new THREE.SphereGeometry(1700, 48, 24), new THREE.ShaderMaterial({
    side: THREE.BackSide, depthWrite: false,
    uniforms: { sunDirection: { value: sunDirection }, phase: { value: 0 } },
    vertexShader: `varying vec3 direction;void main(){direction=position;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);}`,
    fragmentShader: `${peaksGLSL}
      varying vec3 direction;uniform vec3 sunDirection;uniform float phase;
      void main(){vec3 d=normalize(direction);float h=max(d.y,0.);float alignment=max(0.,dot(d,sunDirection));
        float horizon=exp(-h*5.8);
        vec3 c=mix(vec3(.075,.18,.34),vec3(.89,.47,.29),horizon);
        // A broad aureole and a tighter amber halo read even before the disc clears rock.
        float halo=pow(alignment,100.);
        c=mix(c,vec3(.98,.70,.39),halo*.64);
        c=mix(c,vec3(1.,.82,.51),pow(alignment,950.)*.75);
        float disc=smoothstep(.99977,.99984,alignment);
        c=mix(c,vec3(1.35,1.10,.72),disc);
        vec2 cloudUV=d.xz/max(.10,d.y)*vec2(1.5,5.);
        float veil=smoothstep(.52,.76,fbm(cloudUV+vec2(phase*.035,0.)));
        veil*=smoothstep(.025,.12,h)*(1.-smoothstep(.35,.65,h));
        c=mix(c,mix(vec3(.66,.49,.53),vec3(.98,.71,.48),pow(alignment,8.)),veil*.68);
        gl_FragColor=vec4(c,1.);
      }`
  }));
  scene.add(sky); S.sky = sky;
  // Layer widths exceed the entire camera frustum, including the crane's final position.
  S.terrainMaterials = [
    { z:-610,width:1600,depth:210,height:143,seed:41,centers:[[-520,0,280,.9],[-190,-12,170,1],[125,10,200,.92],[470,0,230,1.13]] },
    { z:-420,width:1250,depth:185,height:141,seed:12,centers:[[-440,0,170,.9],[-160,-10,150,1.06],[140,8,175,.9],[390,0,170,1.08]] },
    { z:-247,width:1000,depth:166,height:147,seed:7,centers:[[-310,0,150,1.02],[-75,-16,107,.79],[124,5,118,1.11],[360,-9,135,.9]] },
    { z:-92,width:780,depth:155,height:142,seed:25,centers:[[-270,-5,130,.98],[42,-14,88,1.03],[245,4,108,.88]] },
    { z:49,width:680,depth:133,height:113,seed:32,centers:[[-238,0,112,1.18],[224,8,95,.94]] }
  ].map(c => peaksTerrain(scene, c));

  // An opaque, gently turbulent cloud ceiling fills every valley. Geometry provides
  // parallax and mountain intersections; the shader adds small-scale illuminated billows.
  const cloudGeo = new THREE.PlaneGeometry(1850, 1700, 230, 220);
  cloudGeo.rotateX(-Math.PI / 2);
  const cp = cloudGeo.attributes.position;
  for (let i=0;i<cp.count;i++) {
    const x=cp.getX(i),z=cp.getZ(i)-600;
    cp.setXYZ(i,x,20+9*peaksFbm(x*.025,z*.023)+3*peaksFbm(x*.09,z*.09),z);
  }
  cloudGeo.computeVertexNormals();
  const cloudMat = new THREE.ShaderMaterial({
    uniforms: { phase: { value:0 } },
    vertexShader: `varying vec3 w,n;void main(){w=position;n=normal;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);}`,
    fragmentShader: `${peaksGLSL}
      uniform float phase;varying vec3 w,n;
      void main(){
        vec2 p=w.xz*.072+vec2(phase*.16,phase*.035);
        float a=fbm(p),b=fbm(p+vec2(.17,-.25));
        float ridge=clamp(.5+(a-b)*3.8,0.,1.);
        float top=max(0.,dot(normalize(n),normalize(vec3(.41,.15,-.907))));
        float crown=smoothstep(.30,.65,a)*.42+smoothstep(24.,29.,w.y)*.25;
        float lighting=clamp(crown+ridge*.23+top*.55,0.,1.);
        vec3 shadow=vec3(.24,.35,.52), lit=vec3(.98,.70,.49);
        vec3 color=mix(shadow,lit,smoothstep(.16,.85,lighting));
        color+=vec3(.10,.035,.04)*smoothstep(.48,.72,a);
        color*=.92+.13*a;
        float distance=length(cameraPosition-w);
        color=mix(color,vec3(.69,.51,.46),1.-exp(-distance*.00095));
        gl_FragColor=vec4(color,1.);
      }`
  });
  scene.add(new THREE.Mesh(cloudGeo,cloudMat)); S.cloudMat=cloudMat;

