  s.cam.fov = 47; s.cam.near = 0.1; s.cam.far = 250000; s.cam.updateProjectionMatrix();
  // Keep the sky, water reflection and bloom linear; apply exposure only once, at output.
  s.R.toneMapping = THREE.NoToneMapping;
