    .replace('vec3 surfaceNormal = normalize( noise.xzy * vec3( 1.5, 1.0, 1.5 ) );',
      'vec2 ds = slope(worldPosition.xz); vec3 surfaceNormal = normalize(noise.xzy * vec3(.72,1.0,.72) + vec3(-ds.x,0.0,-ds.y));')
